# @generated by:gauntlet run:godseye-hermes-setup
"""Real ext4 file/lock regressions for Hermes preparation, using disposable state."""

import importlib.util
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch

sys.dont_write_bytecode = True
REPO = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("hermes_files", REPO / "scripts/hermes_files.py")
FILES = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(FILES)


class PrivateFiles(unittest.TestCase):
    def setUp(self) -> None:
        self.temporary = tempfile.TemporaryDirectory(prefix="godseye-hermes-files-")
        self.root = Path(self.temporary.name).resolve()
        self.path = self.root / "active.json"
        self.original = b'{"revision":"fixture-original"}\n'
        self.path.write_bytes(self.original)
        self.path.chmod(0o600)

    def tearDown(self) -> None:
        self.temporary.cleanup()

    def assert_unchanged(self) -> None:
        self.assertEqual(self.path.read_bytes(), self.original)
        self.assertEqual(sorted(item.name for item in self.root.iterdir()), ["active.json"])

    def test_staging_fsync_failure_preserves_previous_active_revision(self) -> None:
        with patch.object(FILES.os, "fsync", side_effect=OSError("fixture full disk")):
            with self.assertRaises(OSError):
                FILES.replace_json(self.path, {"revision": "fixture-new"})
        self.assert_unchanged()

    def test_failed_rename_preserves_previous_active_revision(self) -> None:
        with patch.object(FILES.os, "replace", side_effect=OSError("fixture refused rename")):
            with self.assertRaises(OSError):
                FILES.replace_json(self.path, {"revision": "fixture-new"})
        self.assert_unchanged()

    def test_success_commits_a_complete_private_pointer(self) -> None:
        FILES.replace_json(self.path, {"revision": "fixture-new"})
        self.assertEqual(json.loads(self.path.read_bytes()), {"revision": "fixture-new"})
        self.assertEqual(self.path.stat().st_mode & 0o777, 0o600)
        self.assertEqual(sorted(item.name for item in self.root.iterdir()), ["active.json"])

    def test_postrename_sync_failure_retains_complete_pointer_with_explicit_uncertainty(self) -> None:
        with patch.object(FILES, "sync_directory", side_effect=OSError("fixture durability failure")):
            with self.assertRaises(FILES.DurabilityUncertain):
                FILES.replace_json(self.path, {"revision": "fixture-new"})
        self.assertEqual(json.loads(self.path.read_bytes()), {"revision": "fixture-new"})
        self.assertEqual(self.path.stat().st_mode & 0o777, 0o600)
        self.assertEqual(sorted(item.name for item in self.root.iterdir()), ["active.json"])

    def test_hardlinked_pointer_cannot_modify_another_file(self) -> None:
        alias = self.root / "retained.json"
        os.link(self.path, alias)
        with self.assertRaises(RuntimeError):
            FILES.replace_json(self.path, {"revision": "fixture-new"})
        self.assertEqual(alias.read_bytes(), self.original)
        self.assertEqual(self.path.read_bytes(), self.original)

    def test_symlinked_ancestor_cannot_create_outside_owned_state(self) -> None:
        outside = self.root / "outside"
        outside.mkdir(mode=0o700)
        alias = self.root / "alias"
        alias.symlink_to(outside, target_is_directory=True)
        with self.assertRaises(RuntimeError):
            FILES.private_directory(alias / "profiles")
        self.assertEqual(list(outside.iterdir()), [])

    def test_shared_pointer_is_refused_before_replacement(self) -> None:
        self.path.chmod(0o644)
        with self.assertRaises(RuntimeError):
            FILES.replace_json(self.path, {"revision": "fixture-new"})
        self.assert_unchanged()

    def test_bounded_read_refuses_oversized_state(self) -> None:
        self.path.write_bytes(b"x" * (FILES.MAX_FILE_BYTES + 1))
        with self.assertRaises(RuntimeError):
            FILES.read_bytes(self.path)

    def test_real_os_lock_refuses_a_second_process_and_releases_after_exit(self) -> None:
        script = (
            "import pathlib,sys;sys.path.insert(0,sys.argv[1]);import hermes_files;"
            "\ntry:\n with hermes_files.exclusive(pathlib.Path(sys.argv[2])): print('acquired')"
            "\nexcept BlockingIOError: sys.exit(23)"
        )
        command = [sys.executable, "-I", "-c", script, str(REPO / "scripts"), str(self.root)]
        with FILES.exclusive(self.root):
            blocked = subprocess.run(command, capture_output=True, text=True, timeout=10, check=False)
            self.assertEqual(blocked.returncode, 23, blocked.stderr)
            self.assertEqual(blocked.stdout, "")
        acquired = subprocess.run(command, capture_output=True, text=True, timeout=10, check=False)
        self.assertEqual(acquired.returncode, 0, acquired.stderr)
        self.assertEqual(acquired.stdout.strip(), "acquired")


if __name__ == "__main__":
    unittest.main(verbosity=2)
